using System;
using UnityEngine;

public static class RandomUtilities
{
	public static System.Random RNGSingleton = new System.Random();

	public static bool RandomChance(System.Random rng, int percent)
	{
		return rng.Next(0, 100) < percent;
	}

	public static bool RandomChance(int percent)
	{
		return RandomChance(RNGSingleton, percent);
	}

	public static int RandomInt(System.Random rng, int maximumInt)
	{
		return rng.Next(0, maximumInt);
	}

	public static int RandomInt(System.Random rng, int minimumInt, int maximumInt)
	{
		return rng.Next(minimumInt, maximumInt);
	}

	public static int RandomInt(int maximumInt)
	{
		return RandomInt(RNGSingleton, maximumInt);
	}

	public static int RandomInt(int minimumInt, int maximumInt)
	{
		return RandomInt(RNGSingleton, minimumInt, maximumInt);
	}

	public static void SetUnityEngineRandomInitStateSeed(int seed)
	{
		UnityEngine.Random.InitState(seed);
	}

	public static bool RandomChanceWithSeed(int percent)
	{
		return UnityEngine.Random.Range(0, 101) < percent;
	}

	public static int RandomIntWithSeed(int maximumInt)
	{
		return UnityEngine.Random.Range(0, maximumInt);
	}

	public static int RandomIntWithSeed(int minimumInt, int maximumInt)
	{
		return UnityEngine.Random.Range(minimumInt, maximumInt);
	}

	public static float RandomFloatWithSeed(float minimumFloat, float maximumFloat)
	{
		return UnityEngine.Random.Range(minimumFloat, maximumFloat);
	}
}
